/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <assert.h>
#include <debug.h>

#include <nuttx/irq.h>
#include <nuttx/arch.h>

#include "arm_internal.h"
#include "nvic.h"
#include "ram_vectors.h"

#include "chip.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Default priority applied to every interrupt at start of day */

#define DEFPRIORITY32 \
  (NVIC_SYSH_PRIORITY_DEFAULT << 24 | NVIC_SYSH_PRIORITY_DEFAULT << 16 | \
   NVIC_SYSH_PRIORITY_DEFAULT << 8  | NVIC_SYSH_PRIORITY_DEFAULT)

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_irqinfo
 *
 * Description:
 *   Map an IRQ number onto the register and bit that enable or disable it.
 *   'offset' selects between the set-enable and clear-enable register banks.
 *
 ****************************************************************************/

static int bk7258_irqinfo(int irq, uintptr_t *regaddr, uint32_t *bit,
                          uintptr_t offset)
{
  int n;

  DEBUGASSERT(irq >= NVIC_IRQ_NMI && irq < NR_IRQS);

  /* Peripheral interrupts live in the NVIC enable registers. */

  if (irq >= NVIC_IRQ_FIRST)
    {
      n        = irq - NVIC_IRQ_FIRST;
      *regaddr = NVIC_IRQ_ENABLE(n) + offset;
      *bit     = (uint32_t)1 << (n & 0x1f);
      return OK;
    }

  /* Only a handful of the processor exceptions can be enabled or disabled. */

  *regaddr = NVIC_SYSHCON;

  switch (irq)
    {
      case NVIC_IRQ_MEMFAULT:
        *bit = NVIC_SYSHCON_MEMFAULTENA;
        break;

      case NVIC_IRQ_BUSFAULT:
        *bit = NVIC_SYSHCON_BUSFAULTENA;
        break;

      case NVIC_IRQ_USAGEFAULT:
        *bit = NVIC_SYSHCON_USGFAULTENA;
        break;

      case NVIC_IRQ_SYSTICK:
        *regaddr = NVIC_SYSTICK_CTRL;
        *bit     = NVIC_SYSTICK_CTRL_ENABLE;
        break;

      default:
        return ERROR;
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: up_irqinitialize
 ****************************************************************************/

void up_irqinitialize(void)
{
  int num_priority_registers;
  uintptr_t regaddr;
  int i;

  /* Disable and clear every peripheral interrupt. */

  for (i = 0; i < BK7258_IRQ_NEXTINTS; i += 32)
    {
      putreg32(0xffffffff, NVIC_IRQ_CLEAR(i));
      putreg32(0xffffffff, NVIC_IRQ_CLRPEND(i));
    }

  /* Point the NVIC at our vector table. */

  putreg32((uint32_t)_vectors, NVIC_VECTAB);

#ifdef CONFIG_ARCH_RAMVECTORS
  up_ramvec_initialize();
#endif

  /* Give the configurable system exceptions the default priority. */

  putreg32(DEFPRIORITY32, NVIC_SYSH4_7_PRIORITY);
  putreg32(DEFPRIORITY32, NVIC_SYSH8_11_PRIORITY);
  putreg32(DEFPRIORITY32, NVIC_SYSH12_15_PRIORITY);

  /* NVIC_ICTR bits 0-4 report how many 32-line blocks the NVIC implements,
   * which is eight priority registers per block.
   */

  num_priority_registers = (getreg32(NVIC_ICTR) + 1) * 8;

  regaddr = NVIC_IRQ0_3_PRIORITY;
  while (num_priority_registers--)
    {
      putreg32(DEFPRIORITY32, regaddr);
      regaddr += 4;
    }

  /* Catch the faults we can, so that a bad access reports rather than
   * silently escalating to a hard fault.
   */

#ifdef CONFIG_ARM_MPU
  irq_attach(NVIC_IRQ_MEMFAULT, arm_memfault, NULL);
  up_enable_irq(NVIC_IRQ_MEMFAULT);
#endif

#ifdef CONFIG_DEBUG_FEATURES
  modifyreg32(NVIC_SYSHCON, 0,
              NVIC_SYSHCON_USGFAULTENA | NVIC_SYSHCON_BUSFAULTENA |
              NVIC_SYSHCON_MEMFAULTENA);
#endif

  /* SVCall must be the lowest priority so that it cannot pre-empt a
   * higher-priority handler that is about to switch context.
   */

  up_prioritize_irq(NVIC_IRQ_SVCALL, NVIC_SYSH_SVCALL_PRIORITY);

#ifndef CONFIG_SUPPRESS_INTERRUPTS
  up_irq_enable();
#endif
}

/****************************************************************************
 * Name: up_disable_irq
 ****************************************************************************/

void up_disable_irq(int irq)
{
  uintptr_t regaddr;
  uint32_t regval;
  uint32_t bit;

  if (bk7258_irqinfo(irq, &regaddr, &bit, NVIC_IRQ_CLEAR_OFFSET) == OK)
    {
      if (irq >= NVIC_IRQ_FIRST)
        {
          /* The clear-enable registers are write-1-to-clear. */

          putreg32(bit, regaddr);
        }
      else
        {
          regval  = getreg32(regaddr);
          regval &= ~bit;
          putreg32(regval, regaddr);
        }
    }
}

/****************************************************************************
 * Name: up_enable_irq
 ****************************************************************************/

void up_enable_irq(int irq)
{
  uintptr_t regaddr;
  uint32_t regval;
  uint32_t bit;

  if (bk7258_irqinfo(irq, &regaddr, &bit, NVIC_IRQ_ENABLE_OFFSET) == OK)
    {
      if (irq >= NVIC_IRQ_FIRST)
        {
          /* The set-enable registers are write-1-to-set. */

          putreg32(bit, regaddr);
        }
      else
        {
          regval  = getreg32(regaddr);
          regval |= bit;
          putreg32(regval, regaddr);
        }
    }
}

/****************************************************************************
 * Name: up_prioritize_irq
 ****************************************************************************/

int up_prioritize_irq(int irq, int priority)
{
  uintptr_t regaddr;
  uint32_t regval;
  int shift;

  DEBUGASSERT(irq >= NVIC_IRQ_MEMFAULT && irq < NR_IRQS &&
              (unsigned)priority <= NVIC_SYSH_PRIORITY_MIN);

  if (irq < NVIC_IRQ_FIRST)
    {
      /* System handler priorities start at exception 4. */

      regaddr = NVIC_SYSH_PRIORITY(irq);
      irq    -= 4;
    }
  else
    {
      irq    -= NVIC_IRQ_FIRST;
      regaddr = NVIC_IRQ_PRIORITY(irq);
    }

  shift   = ((irq & 3) << 3);
  regval  = getreg32(regaddr);
  regval &= ~((uint32_t)0xff << shift);
  regval |= ((uint32_t)priority << shift);
  putreg32(regval, regaddr);

  return OK;
}

