    def from_bytes(cls, data: bytes):
        header = cls(*cls.FORMAT.unpack(data))
        header.algo = OTAAlgorithm(header.algo)
        cls.__validate_data(data, info_crc32=header.info_crc32)

        def __clean_c_string(x):
