      volatile uint32_t spin;

      for (spin = 0; spin < 3000000; spin++)
        {
        }

      putreg32(NVIC_AIRCR_VECTKEY | NVIC_AIRCR_SYSRESETREQ, NVIC_AIRCR);

      __asm__ __volatile__ ("dsb 0xf" : : : "memory");
    }
